def blocks(g):
    h,w=len(g),len(g[0]); seen=[[False]*w for _ in range(h)]; res=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]==2 and not seen[i][j]:
                # find bounding box of connected component (4-conn)
                stack=[(i,j)]; comp=[]
                seen[i][j]=True
                while stack:
                    r,c=stack.pop(); comp.append((r,c))
                    for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
                        nr,nc=r+dr,c+dc
                        if 0<=nr<h and 0<=nc<w and g[nr][nc]==2 and not seen[nr][nc]:
                            seen[nr][nc]=True; stack.append((nr,nc))
                rs=[r for r,c in comp]; cs=[c for r,c in comp]
                res.append((min(rs),min(cs),max(rs),max(cs)))
    return res
