    for r in range(h):
        for c in range(w):
            if g[r][c]==2 and not seen[r][c]:
                stack=[(r,c)]; seen[r][c]=True; cells=[]
                while stack:
                    y,x=stack.pop(); cells.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and g[ny][nx]==2 and not seen[ny][nx]:
                            seen[ny][nx]=True; stack.append((ny,nx))
                rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
                out.append((min(rs),min(cs),max(rs),max(cs)))
    return out

def transform(grid):
    g=[row[:] for row in grid]
    B=sorted(blocks(g), key=lambda b:b[1])
    n=len(B)
    for i,b in enumerate(B):
        rank_from_right = n-1-i
        if rank_from_right%2==0:
            r1,c1,r2,c2=b
            for r in range(r1,r2+1):
                for c in range(c1,c2+1):
                    g[r][c]=8
